<script setup>
import { computed, ref } from 'vue'
const tab = ref('position'), position = ref('relative'), direction = ref('row'), justify = ref('space-between'), columns = ref(3), unit = ref('rem')
const tabs = [['position','Position'],['flex','Flexbox'],['grid','Grid'],['units','Единицы']]
const positionText = { static:['Обычный поток','Как слой в Auto Layout без ручного смещения.'], relative:['Смещение от себя','Как слой Auto Layout, визуально сдвинутый без изменения порядка.'], absolute:['Свободный слой','Как Absolute position внутри фрейма Figma: не двигает соседей.'], fixed:['Закреплён у окна','Как Fix position when scrolling в прототипе.'], sticky:['Поток, затем закрепление','Как заголовок, который закрепляется при прокрутке.'] }
const posStyle = computed(() => ({ position: position.value, top: position.value === 'relative' ? '-10px' : ['absolute','fixed','sticky'].includes(position.value) ? '12px' : 'auto', right: ['absolute','fixed'].includes(position.value) ? '12px' : 'auto' }))
const flexStyle = computed(() => ({ display:'flex', flexDirection:direction.value, justifyContent:justify.value, gap:'12px', flexWrap:'wrap', minHeight:'180px' }))
const gridStyle = computed(() => ({ display:'grid', gridTemplateColumns:`repeat(${columns.value}, minmax(0, 1fr))`, gap:'12px' }))
const units = { px:['Фиксированная CSS-точка','Точные небольшие детали: границы, иконки.'], '%':['Доля родителя','Ширина зависит от контейнера.'], rem:['От корневого текста','Удобно для масштабируемой типографики и токенов.'], em:['От текущего текста','Полезно локально, но может накапливаться во вложенности.'], vw:['Доля окна браузера','Размер зависит от viewport.'], fr:['Доля свободного Grid','Работает внутри CSS Grid.'] }
</script>
<template><div class="flex flex-col gap-6"><header><h1 class="text-2xl font-extrabold text-slate-900">Справочник CSS</h1><p class="mt-1 text-slate-500">Меняйте свойства — схема и код обновляются плавно.</p></header><nav class="flex flex-wrap gap-2"><button v-for="item in tabs" :key="item[0]" class="rounded-full px-4 py-2 text-sm font-semibold transition" :class="tab===item[0]?'bg-brand-gradient text-slate-800 shadow-sm':'bg-white text-slate-600 ring-1 ring-slate-200'" @click="tab=item[0]">{{ item[1] }}</button></nav>
<section v-if="tab==='position'" class="flex flex-col gap-4"><div class="card p-5"><div class="flex flex-wrap gap-2"><button v-for="(_, name) in positionText" :key="name" class="rounded-lg px-3 py-2 font-mono text-sm" :class="position===name?'bg-slate-800 text-white':'bg-slate-100 text-slate-600'" @click="position=name">{{ name }}</button></div><div class="relative mt-5 min-h-56 overflow-hidden rounded-xl border border-dashed border-slate-300 bg-slate-50 p-5"><div class="mt-10 flex gap-3"><div class="rounded-lg bg-white p-4 shadow-sm">Сосед</div><div class="rounded-lg bg-white p-4 shadow-sm">Сосед</div></div><div class="rounded-lg bg-brand-gradient p-4 font-semibold transition-all duration-500 ease-out" :style="posStyle">Выбранный блок</div></div></div><div class="card p-5"><h2 class="font-bold">{{ positionText[position][0] }}</h2><p class="mt-2 text-slate-600">{{ positionText[position][1] }}</p><pre class="mt-4 rounded-xl bg-slate-950 p-4 text-sm text-slate-200"><code>position: {{ position }};</code></pre></div></section>
<section v-else-if="tab==='flex'" class="flex flex-col gap-4"><div class="card p-5"><div class="flex flex-wrap gap-3"><label>Направление <select v-model="direction" class="ml-2 rounded border p-2"><option>row</option><option>column</option></select></label><label>Распределение <select v-model="justify" class="ml-2 rounded border p-2"><option>space-between</option><option>center</option><option>flex-start</option></select></label></div><div class="mt-5 rounded-xl border border-dashed border-slate-300 bg-slate-50 p-5 transition-all duration-500" :style="flexStyle"><div v-for="n in 4" :key="n" class="rounded-xl bg-brand-gradient p-4 text-center font-bold transition-all duration-500">{{ n }}</div></div></div><div class="card p-5 text-slate-600">Flexbox — веб-аналог <strong>Auto Layout</strong>: <code>flex-direction</code> задаёт главную ось, <code>justify-content</code> распределяет элементы по ней.<pre class="mt-4 rounded-xl bg-slate-950 p-4 text-sm text-slate-200"><code>display: flex;
flex-direction: {{ direction }};
justify-content: {{ justify }};</code></pre></div></section>
<section v-else-if="tab==='grid'" class="flex flex-col gap-4"><div class="card p-5"><label>Колонки <input v-model.number="columns" type="range" min="2" max="4" class="ml-2"><span>{{ columns }}</span></label><div class="mt-5 rounded-xl border border-dashed border-slate-300 bg-slate-50 p-5 transition-all duration-500" :style="gridStyle"><div v-for="n in 8" :key="n" class="min-h-20 rounded-xl bg-brand-gradient p-3 font-bold transition-all duration-500">{{ n }}</div></div></div><div class="card p-5 text-slate-600">Grid похож на сетку фрейма Figma: вы управляете рядами и колонками одновременно.<pre class="mt-4 rounded-xl bg-slate-950 p-4 text-sm text-slate-200"><code>display: grid;
grid-template-columns: repeat({{ columns }}, 1fr);</code></pre></div></section>
<section v-else class="flex flex-col gap-4"><div class="card p-5"><div class="flex flex-wrap gap-2"><button v-for="(_, name) in units" :key="name" class="rounded-lg px-3 py-2 font-mono" :class="unit===name?'bg-slate-800 text-white':'bg-slate-100 text-slate-600'" @click="unit=name">{{ name }}</button></div><div class="mt-5 rounded-xl border border-dashed border-slate-300 bg-slate-50 p-6"><div class="rounded-xl bg-brand-gradient p-5 text-center font-bold transition-all duration-500" :style="{width: unit==='px'?'160px':unit==='%'?'60%':unit==='vw'?'55vw':'18rem',maxWidth:'100%'}">Размер в {{ unit }}</div></div></div><div class="card p-5"><h2 class="font-bold">{{ unit }}</h2><p class="mt-2 text-slate-600">{{ units[unit][0] }}. {{ units[unit][1] }}</p><p class="mt-3 text-sm text-slate-500">Аналогия с Figma: {{ unit==='fr'?'пропорциональные колонки сетки':unit==='%'?'Fill container':'системный размер или token' }}.</p></div></section></div></template>
